CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE workspaces (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id), email text NOT NULL, name text NOT NULL, UNIQUE (workspace_id, email));
CREATE TABLE feature_flags (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), name text NOT NULL, key text NOT NULL, description text NOT NULL DEFAULT '', default_enabled boolean NOT NULL DEFAULT false, created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (workspace_id, key));
CREATE TABLE environments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), name text NOT NULL, key text NOT NULL, UNIQUE (workspace_id, key));
CREATE TABLE feature_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), flag_id uuid NOT NULL REFERENCES feature_flags(id) ON DELETE CASCADE, environment_id uuid REFERENCES environments(id) ON DELETE CASCADE, enabled boolean NOT NULL, rollout_percentage integer CHECK (rollout_percentage BETWEEN 0 AND 100), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (flag_id, environment_id));
CREATE TABLE feature_overrides (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), flag_id uuid NOT NULL REFERENCES feature_flags(id) ON DELETE CASCADE, environment_id uuid NOT NULL REFERENCES environments(id) ON DELETE CASCADE, target_type text NOT NULL CHECK (target_type IN ('user','organization')), target_id text NOT NULL, enabled boolean NOT NULL, UNIQUE (flag_id, environment_id, target_type, target_id));
CREATE TABLE api_keys (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), environment_id uuid REFERENCES environments(id), name text NOT NULL, key_prefix text NOT NULL, key_hash text NOT NULL UNIQUE, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), actor_id uuid REFERENCES users(id), entity_type text NOT NULL, entity_id uuid NOT NULL, action text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX flag_evaluation_idx ON feature_overrides (flag_id, environment_id, target_type, target_id);
